package app.morphe.extension.shared;

import java.util.Map;

/**
 * Hushfacebook's text in every language the bundle carries, one L10nTable class per language.
 *
 * <p>Generated by scripts/gen-l10n.py from extensions/shared/library/src/main/l10n. Don't
 * edit it by hand: edit the table and run the script.
 */
public final class L10nTranslations {
    private L10nTranslations() {
    }

    /** The language tags with a table, lower case. */
    static final String[] LANGUAGES = {"de", "es", "in", "pt-rbr", "ru", "tr", "vi", "zh-rcn", "zh-rtw"};

    /**
     * The table for one language tag, or null when nothing was translated into it.
     * A language with two ISO codes answers to both, because Android reports the
     * legacy one and a desktop JVM reports the new one.
     */
    static Map<String, String> of(String language) {
        switch (language) {
            case "de":
                return L10nTableDe.build();
            case "es":
                return L10nTableEs.build();
            case "in":
            case "id":
                return L10nTableIn.build();
            case "pt-rbr":
                return L10nTablePt_rBR.build();
            case "ru":
                return L10nTableRu.build();
            case "tr":
                return L10nTableTr.build();
            case "vi":
                return L10nTableVi.build();
            case "zh-rcn":
                return L10nTableZh_rCN.build();
            case "zh-rtw":
                return L10nTableZh_rTW.build();
            default:
                return null;
        }
    }
}
